# Out_BalanceAnalys/DataModuleBalance.dfm:12 Balance (TOracleDataSet)
SQL_OBA_BALANCE = '  SELECT   lastremainder.balancebill AS balanceaccount,\n         firstremainder.active AS firstactive,\n         firstremainder.passive AS firstpassive,\n         turnovers.dturnover,\n         turnovers.cturnover,\n         lastremainder.active AS lastactive,\n         lastremainder.passive AS lastpassive\n    FROM (SELECT   b.bal_cn balancebill,\n                   SUM (\n                      out_sb_mtoutview.active (\n                         ar.%sostat, /*10*/\n                         b.typeid,\n                         b.additionaltypeid\n                      )\n                   ) active,\n                   SUM (\n                      out_sb_mtoutview.passiv (\n                         ar.%sostat,     /*17*/\n                         b.typeid,\n                         b.additionaltypeid\n                      )\n                   ) passive\n              FROM out_archost ar, out_ACCOUNT ac, out_bal_spr%d b /*22*/\n             WHERE (ar.acc_id = ac.id)\n               AND (ac.bal_cn%d = b.bal_cn)    /*24*/\n               /*25 BRANCH and CURRENCY*/\n               AND (ar.datdate = :BeginPeriod)\n          GROUP BY\n           b.bal_cn) firstremainder,\n         (SELECT   b.bal_cn balancebill,\n                   SUM (ar.%sobr_d) dturnover,/*30*/\n                   SUM (ar.%sobr_k) cturnover /*31*/\n              FROM out_archost ar, out_ACCOUNT ac, out_bal_spr%d b /*32*/\n             WHERE (ar.acc_id = ac.id)\n               AND (ac.bal_cn%d = b.bal_cn)                 /*34*/\n               /*35 BRANCH and CURRENCY*/\n               AND (ar.datdate BETWEEN :BeginDate AND :EndDate)\n          GROUP BY b.bal_cn) turnovers,\n         (SELECT  b.bal_cn balancebill,\n                   SUM (\n                      out_sb_mtoutview.active (\n                         ar.%sostat,/*41*/\n                         b.typeid,\n                         b.additionaltypeid\n                      )\n                   ) active,\n                   SUM (\n                      out_sb_mtoutview.passiv (\n                         ar.%sostat,/*48*/\n                         b.typeid,\n                         b.additionaltypeid\n                      )\n                   ) passive\n              FROM out_archost ar, out_ACCOUNT ac, out_bal_spr%d b  /*53*/\n             WHERE (ar.acc_id = ac.id)\n               AND (ac.bal_cn%d = b.bal_cn)  /*55*/\n               /*56 BRANCH and CURRENCY*/\n               AND (ar.datdate = :EndDate)\n          GROUP BY\n           b.bal_cn) lastremainder\n   WHERE\n    lastremainder.balancebill = firstremainder.balancebill(+)\n     AND lastremainder.balancebill = turnovers.balancebill\nORDER BY lastremainder.balancebill\n\n\n\n\n\n\n\n\n\n \n \n \n '

# Out_BalanceAnalys/DataModuleBalance.dfm:173 Account (TOracleDataSet)
SQL_OBA_ACCOUNT = 'select\n  RestForLastPeriod.AccountID , RestForLastPeriod.Name ,\n  RestForLastPeriod.AccNo ,\n  RestForLastPeriod.CurrencyID ,\n  RestForLastPeriod.BranchID ,\n  RestForLastPeriod.BalanceNo ,\n  RestForFirstPeriod.Active as BeginActive ,\n  RestForFirstPeriod.Passive as BeginPassive ,\n  TurnOvers.DTurnOver ,\n  TurnOvers.CTurnOver ,\n  RestForLastPeriod.Active as EndActive ,\n  RestForLastPeriod.Passive as EndPassive\nfrom\n\n(select\n  ac.ID as AccountID ,\n  ac.acc_no as AccNo ,\n  b.bal_cn  as BalanceNo ,\n\n  out_sb_mtoutview.active (\n    ar.%sostat,  /*20*/\n    b.typeid,\n    b.additionaltypeid\n  ) as Active ,\n\n  out_sb_mtoutview.passiv (\n     ar.%sostat,   /*26*/\n     b.typeid,\n     b.additionaltypeid\n  ) as Passive\n\nfrom\n  out_account ac ,\n  out_archost ar ,\n  out_bal_spr%d b  /*34*/\nwhere\n  ar.acc_id = ac.id and\n  ac.bal_cn%d = b.bal_cn and     /*37*/\n  ar.DatDate = :BeginPeriod and\n  ((ac.Close_Dat is null)or(ac.Close_Dat > :BeginPeriod))\n) RestForFirstPeriod ,\n\n(select\n  ac.ID as AccountID , ac.name ,\n  ac.acc_no as AccNo ,\n  ac.val_acc as CurrencyID ,\n  ac.filial as BranchID ,\n  b.bal_cn  as BalanceNo ,\n\n  out_sb_mtoutview.active (\n    ar.%sostat,  /*50*/\n    b.typeid,\n    b.additionaltypeid\n  ) as Active ,\n\n  out_sb_mtoutview.passiv (\n     ar.%sostat,  /*56*/\n     b.typeid,\n     b.additionaltypeid\n  ) as Passive\n\nfrom\n  out_account ac ,\n  out_archost ar ,\n  out_bal_spr%d b  /*64*/\nwhere\n  ar.acc_id = ac.id and\n  ac.bal_cn%d = b.bal_cn and  /*67*/\n  ar.DatDate = :EndDate and\n  ((ac.Close_Dat is null)or(ac.Close_Dat > :EndDate))\n) RestForLastPeriod ,\n\n(select\n  ac.ID as AccountID ,\n  min(ac.acc_no) as AccNo,\n  min(b.bal_cn)  as BalanceNo ,\n  sum(ar.%sObr_D) as DTurnOver , /*76*/\n  sum(ar.%sObr_K) as CTurnOver   /*77*/\nfrom\n  out_account ac ,\n  out_archost ar ,\n  out_bal_spr%d b  /*81*/\nwhere\n  ar.acc_id = ac.id and\n  ac.bal_cn%d = b.bal_cn and /*84*/\n  ar.DatDate between :BeginDate and :EndDate\ngroup by\n  ac.ID\n) TurnOvers\n\nwhere\n  /* Branch & Currency*/\n  RestForLastPeriod.AccountID = RestForFirstPeriod.AccountID  (+) and\n  RestForLastPeriod.AccountID = TurnOvers.AccountID\n  --and\n  --RestForLastPeriod.BalanceNo =:BalanceNo\n\norder by\n  RestForLastPeriod.AccNo\n \n \n\n \n \n \n'

# Out_BalanceAnalys/DataModuleBalance.dfm:375 Transaction (TOracleDataSet)
SQL_OBA_TRANSACTION = 'select\n      t.ID,t.op_id as OperatorID, t.vid_op as OperationType,\n      t.dat, t.DEBT, d.acc_no as DebtAcc, dv.val_name as DValName,\n      t.KREDIT, c.acc_no as CreditAcc, cv.val_name as CValName,\n      t.ammount, t.ammount_c, t.lammount, t.name, SB_EXPERTANALYSE.GetUserName(t.op_id) as UserName\nfrom\n      out_provarch t,\n      out_account d,\n      out_account c,\n      avalute dv,\n      avalute cv\nwhere\n     t.DEBT = d.ID and\n     t.KREDIT = c.ID and\n     t.val_acc = dv.valute and\n     t.currencyID_c = cv.valute and\n     /* 16 Operator & Operation Type*/\n     t.dat between :BeginDate and :EndDate\norder by\n     :Title\n\n \n '

